def solve(n):
    """Return the count of prime numbers strictly less than n.
    Uses Sieve of Eratosthenes.
    """
    if n <= 2:
        return 0
    limit = n
    sieve = bytearray(b'\x01') * limit
    sieve[0:2] = b'\x00\x00'
    import math
    for p in range(2, int(math.isqrt(limit - 1)) + 2):
        if sieve[p]:
            step = p
            start = p * p
            if start >= limit:
                continue
            sieve[start:limit:step] = b'\x00' * ((limit - 1 - start) // step + 1)
    return sum(sieve)

