def solve(coins, amount):
    """Return the minimum number of coins needed to make up *amount* using unlimited coins from *coins*.
    If it is impossible, return -1.
    """
    # Filter out non‑positive coin values to avoid infinite loops.
    filtered = [c for c in coins if c > 0]
    if amount < 0:
        return -1
    if amount == 0:
        return 0
    if not filtered:
        return -1
    # Initialize DP array where dp[i] is the fewest coins to make amount i.
    INF = amount + 1  # larger than any possible number of coins
    dp = [INF] * (amount + 1)
    dp[0] = 0
    for c in filtered:
        for i in range(c, amount + 1):
            # If i-c is reachable, update dp[i]
            if dp[i - c] + 1 < dp[i]:
                dp[i] = dp[i - c] + 1
    return dp[amount] if dp[amount] != INF else -1

