    If impossible, return -1.
    Uses bottom‑up DP with O(amount * len(coins)) time.
    """
    if amount < 0:
        return -1
    # DP array where dp[i] is min coins for amount i
    dp = [float('inf')] * (amount + 1)
    dp[0] = 0
    for coin in coins:
        if coin <= 0:
            continue  # ignore non‑positive coin values
        for i in range(coin, amount + 1):
            if dp[i - coin] + 1 < dp[i]:
                dp[i] = dp[i - coin] + 1
